function h(string $v): string { return htmlspecialchars($v,ENT_QUOTES,'UTF-8'); }
function go(string $view='feed'): never { header('Location:/?view='.rawurlencode($view)); exit; }
function create_entity_full(string $uid,array $in): array {
    $type=(string)($in['type']??''); $name=trim((string)($in['name']??''));
    if(!in_array($type,['page','business','community','event','opportunity','place'],true)||mb_strlen($name)<2) return [false,'أكمل بيانات الإنشاء.'];
    $rows=oyya_read('entities');
    $rows[]=['id'=>oyya_id(),'owner_id'=>$uid,'type'=>$type,'name'=>$name,'description'=>trim((string)($in['description']??'')),'city'=>trim((string)($in['city']??'')),'address'=>trim((string)($in['address']??'')),'contact'=>trim((string)($in['contact']??'')),'lat'=>(float)($in['lat']??0),'lng'=>(float)($in['lng']??0),'created_at'=>oyya_now()];
    oyya_write('entities',$rows); return [true,'تم الإنشاء.'];
}

$message=''; $error=false; $user=oyya_current_user();
if($_SERVER['REQUEST_METHOD']==='POST'){
    $a=(string)($_POST['action']??'');
    if($a==='register'){[$ok,$message]=oyya_register($_POST);$error=!$ok;if($ok)go('feed');}
    elseif($a==='login'){[$ok,$message]=oyya_login($_POST);$error=!$ok;if($ok)go('feed');}
    elseif($a==='logout'){oyya_logout();header('Location:/');exit;}
    else{
        $user=oyya_current_user(); if(!$user){header('Location:/');exit;} $uid=(string)$user['id']; $ok=true;
        if($a==='post')[$ok,$message]=oyya_create_media_post($uid,$_POST,$_FILES['media']??null);
        elseif($a==='like')oyya_toggle_like($uid,(string)($_POST['post_id']??''));
        elseif($a==='save')oyya_toggle_save($uid,(string)($_POST['post_id']??''));
        elseif($a==='comment')[$ok,$message]=oyya_add_comment($uid,(string)($_POST['post_id']??''),(string)($_POST['text']??''));
        elseif($a==='audio_comment')[$ok,$message]=oyya_add_audio_comment($uid,(string)($_POST['post_id']??''),$_FILES['voice']??[]);
        elseif($a==='follow')oyya_toggle_follow($uid,(string)($_POST['target_id']??''));
        elseif($a==='friend')[$ok,$message]=oyya_friend_request($uid,(string)($_POST['target_id']??''));
        elseif($a==='friend_respond')oyya_friend_respond($uid,(string)($_POST['request_id']??''),(string)($_POST['status']??'declined'));
        elseif($a==='profile')[$ok,$message]=oyya_profile_update($uid,$_POST);
        elseif($a==='location')[$ok,$message]=oyya_location_set($uid,(float)($_POST['lat']??999),(float)($_POST['lng']??999));
        elseif($a==='entity')[$ok,$message]=create_entity_full($uid,$_POST);
        elseif($a==='membership')oyya_toggle_membership($uid,(string)($_POST['entity_id']??''));
        elseif($a==='gallery')[$ok,$message]=oyya_entity_gallery_add($uid,(string)($_POST['entity_id']??''),$_FILES['media']??[],(string)($_POST['caption']??''));
        elseif($a==='message')[$ok,$message]=oyya_send_message($uid,(string)($_POST['to_id']??''),(string)($_POST['text']??''));
        elseif($a==='notifications_read'){oyya_mark_notifications_read($uid);$message='تم تعليم النشاط كمقروء.';}
        elseif($a==='verify')[$ok,$message]=oyya_request_verification($uid);
        elseif($a==='reel'){$up=oyya_upload_media($uid,$_FILES['video']??[],'reel');if($up[0])[$ok,$message]=oyya_create_reel($uid,(string)($_POST['caption']??''),(string)$up[1]);else{$ok=false;$message=(string)$up[1];}}
        elseif($a==='album'){[$ok,$albumId]=oyya_create_album($uid,(string)($_POST['title']??''));$message=$ok?'تم إنشاء الألبوم.':(string)$albumId;if($ok&&isset($_FILES['media'])&&($_FILES['media']['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_OK){$up=oyya_upload_media($uid,$_FILES['media'],'album');if($up[0])oyya_album_add($uid,(string)$albumId,(string)$up[1]);}}
        elseif($a==='ad')[$ok,$message]=oyya_create_ad($uid,$_POST);
        elseif($a==='game_create'){[$ok,$id]=oyya_create_game_room($uid,(string)($_POST['name']??''),(int)($_POST['max_players']??6));$message=$ok?'تم إنشاء الطاولة.':(string)$id;}
        elseif($a==='game_join')[$ok,$message]=oyya_join_game($uid,(string)($_POST['room_id']??''));
        elseif($a==='game_play')[$ok,$message]=oyya_game_play($uid,(string)($_POST['room_id']??''));
        elseif($a==='delete_account'){if(oyya_delete_account($uid)){oyya_logout();header('Location:/');exit;}else{$ok=false;$message='تعذر حذف الحساب.';}}
        $error=!$ok; go(preg_replace('/[^a-z_]/','',(string)($_POST['return_view']??'feed'))?:'feed');
    }
}

$user=oyya_current_user(); $users=oyya_users(); $usersCount=count($users); $remaining=max(0,OYYA_MAX_USERS-$usersCount); $view=(string)($_GET['view']??'feed');
$allowed=['feed','following','nearby','people','map','communities','events','opportunities','saved','profile','messages','notifications','games','reels','explore','pages','albums','memories','ads']; if(!in_array($view,$allowed,true))$view='feed';
