<div class="audioDock"><button type="button" id="radioToggle">▶</button><input type="checkbox" id="adhanToggle"><input type="range" id="volume" min="0" max="1" step=".01" value=".25"></div>
<?php endif;?></div><script>
document.querySelectorAll('.tab').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.tab').forEach(x=>x.classList.remove('on'));document.querySelectorAll('.form').forEach(x=>x.classList.remove('on'));b.classList.add('on');document.getElementById(b.dataset.target)?.classList.add('on')}));
if('serviceWorker' in navigator)addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(()=>{}));
const geo=document.getElementById('geoBtn');if(geo)geo.addEventListener('click',()=>{if(!navigator.geolocation)return alert('الموقع غير مدعوم');navigator.geolocation.getCurrentPosition(p=>{document.getElementById('lat').value=p.coords.latitude;document.getElementById('lng').value=p.coords.longitude;document.getElementById('locationForm').submit()},()=>alert('تعذر قراءة الموقع'))});
document.querySelectorAll('.recordVoice').forEach(btn=>btn.addEventListener('click',async()=>{if(!navigator.mediaDevices?.getUserMedia)return alert('التسجيل غير مدعوم');const form=btn.closest('.voiceForm');try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});const rec=new MediaRecorder(stream);const chunks=[];rec.ondataavailable=e=>chunks.push(e.data);rec.onstop=()=>{const blob=new Blob(chunks,{type:rec.mimeType||'audio/webm'});const file=new File([blob],'voice.webm',{type:blob.type});const dt=new DataTransfer();dt.items.add(file);form.querySelector('.voiceInput').files=dt.files;stream.getTracks().forEach(t=>t.stop());btn.textContent='✓ جاهز للإرسال'};rec.start();btn.textContent='■ إيقاف';const stop=()=>{if(rec.state==='recording')rec.stop();btn.removeEventListener('click',stop)};btn.addEventListener('click',stop)}catch(e){alert('تعذر تشغيل الميكروفون')}}));
const rb=document.getElementById('radioToggle'),vol=document.getElementById('volume'),adhan=document.getElementById('adhanToggle');if(rb){let ctx=null,master=null,timer=null,playing=false,i=0;const seq=[220,261.63,329.63,392,329.63,261.63];const note=()=>{const o=ctx.createOscillator(),g=ctx.createGain();o.type='sine';o.frequency.value=seq[i++%seq.length];g.gain.setValueAtTime(.001,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.07,ctx.currentTime+.05);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.75);o.connect(g);g.connect(master);o.start();o.stop(ctx.currentTime+.8)};rb.addEventListener('click',async()=>{if(playing){clearInterval(timer);timer=null;playing=false;rb.textContent='▶';return}ctx=ctx||new(window.AudioContext||window.webkitAudioContext)();await ctx.resume();master=master||ctx.createGain();if(!master._x){master.connect(ctx.destination);master._x=true}master.gain.value=Number(vol.value);note();timer=setInterval(note,850);playing=true;rb.textContent='❚❚'});vol.addEventListener('input',()=>{if(master)master.gain.value=Number(vol.value)});adhan.checked=localStorage.getItem('oyya_adhan')==='1';adhan.addEventListener('change',()=>localStorage.setItem('oyya_adhan',adhan.checked?'1':'0'))}
</script></body></html>